import { useEffect, useState, useRef, RefObject } from 'react';

/**
 * Hook to track which slide is currently in the viewport
 * and update URL hash accordingly
 */
export const useScrollSpy = (
  slideRefs: RefObject<HTMLElement | null>[],
  slideIds: string[],
  enabled: boolean = true
): number => {
  const [activeIndex, setActiveIndex] = useState(0);
  const observerRef = useRef<IntersectionObserver | null>(null);
  const intersectionMapRef = useRef<Map<string, number>>(new Map());

  useEffect(() => {
    console.log('[ScrollSpy] Effect triggered', { 
      enabled, 
      refsCount: slideRefs.length, 
      idsCount: slideIds.length,
      ids: slideIds 
    });
    
    if (!enabled || slideRefs.length === 0) {
      console.log('[ScrollSpy] Skipping - disabled or no refs');
      return;
    }

    // Clean up previous observer
    if (observerRef.current) {
      console.log('[ScrollSpy] Disconnecting previous observer');
      observerRef.current.disconnect();
    }

    // Reset intersection map
    intersectionMapRef.current = new Map();

    // Check which refs are actually populated
    const populatedRefs = slideRefs.filter(ref => ref.current !== null);
    console.log('[ScrollSpy] Populated refs:', populatedRefs.length, 'out of', slideRefs.length);
    
    if (populatedRefs.length === 0) {
      console.warn('[ScrollSpy] No populated refs found!');
      return;
    }

    // Create new IntersectionObserver
    observerRef.current = new IntersectionObserver(
      (entries) => {
        console.log('[ScrollSpy] Observer callback triggered with', entries.length, 'entries');
        entries.forEach((entry) => {
          console.log('[ScrollSpy] Entry:', {
            id: entry.target.id,
            isIntersecting: entry.isIntersecting,
            ratio: entry.intersectionRatio
          });
          if (entry.target.id) {
            // Store intersection ratio for each slide
            if (entry.isIntersecting) {
              intersectionMapRef.current.set(entry.target.id, entry.intersectionRatio);
            } else {
              intersectionMapRef.current.delete(entry.target.id);
            }
          }
        });

        // Find the slide with highest intersection ratio
        let maxRatio = 0;
        let maxId = '';
        intersectionMapRef.current.forEach((ratio, id) => {
          if (ratio > maxRatio) {
            maxRatio = ratio;
            maxId = id;
          }
        });

        console.log('[ScrollSpy] Current intersections:', Array.from(intersectionMapRef.current.entries()));
        console.log('[ScrollSpy] Max intersection:', { maxId, maxRatio });

        if (maxId) {
          const index = slideIds.indexOf(maxId);
          if (index !== -1) {
            console.log(`[ScrollSpy] Checking slide: ${maxId} (index: ${index}, current active: ${activeIndex})`);
            if (index !== activeIndex) {
              console.log(`[ScrollSpy] ✓ Active slide changed to: ${maxId} (index: ${index})`);
              setActiveIndex(index);
              
              // Update URL hash without scrolling
              const newHash = `#${maxId}`;
              if (window.location.hash !== newHash) {
                window.history.replaceState(null, '', newHash);
              }
            }
          }
        }
      },
      {
        root: null,
        rootMargin: '-20% 0px -20% 0px', // Trigger when 20% visible from top/bottom
        threshold: [0, 0.25, 0.5, 0.75, 1.0], // Multiple thresholds for better tracking
      }
    );

    console.log('[ScrollSpy] Created observer, observing elements...');

    // Observe all slide elements
    slideRefs.forEach((ref, index) => {
      if (ref.current) {
        console.log(`[ScrollSpy] Observing element ${index}:`, ref.current.id, ref.current);
        observerRef.current?.observe(ref.current);
      } else {
        console.warn(`[ScrollSpy] Ref ${index} has no current element`);
      }
    });

    return () => {
      console.log('[ScrollSpy] Cleanup');
      observerRef.current?.disconnect();
    };
  }, [slideRefs, slideIds, enabled]);

  return activeIndex;
};
